+        while (dir is not null)
+        {
+            if (Directory.GetFiles(dir, "*.slnx").Length > 0 ||
+                Directory.GetFiles(dir, "*.sln").Length > 0)
+                return dir;
+            dir = Directory.GetParent(dir)?.FullName;
+        }
+        return AppContext.BaseDirectory;
